def numDecodings(s: str) -> int:
    def solve(index):
        if index == len(s):
            return 1
        if s[index] == '0':
            return 0
        ways = solve(index + 1)
        if index + 1 < len(s) and int(s[index:index+2]) <= 26:
            ways += solve(index + 2)
        return ways
    return solve(0)

